import {sample,validate,calculate,journals,initialJournals,reclassJournalRows,classificationTest,ibrBuildUp,csv,extract,extractCsv,round2} from './engine.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const classificationDefaults={ownershipTransfer:false,purchaseOption:false,economicLifeMonths:480,fairValue:40000000,specializedAsset:false,termThreshold:75,pvThreshold:90};
const ibrDefaults={reference:6,spread:1.5,adjustment:0.5};
let state={view:'intake',data:{...sample},extracted:false,approved:false,evidence:{},filename:'sample-lease.pdf',source:'pdf',month:4,tab:'liability',route:'liability',journalMode:'monthly',framework:'asc842',classification:{...classificationDefaults},ibr:{...ibrDefaults},gl:null,scenario:'missing',projected:false,error:'',busy:false,log:[]};
const labels={entity:'Lessee entity',currency:'Currency',start:'Commencement date',months:'Lease term (months)',rent:'Monthly base rent',escalation:'Annual fixed increase (%)',free:'Initial rent-free months',incentive:'Incentive received at commencement',rate:'Annual nominal discount rate (%)',prepayment:'Prepaid rent at commencement',idc:'Qualifying initial direct costs',type:'Lease classification'};
function money(n,decimals=0){return new Intl.NumberFormat('en-IN',{style:'currency',currency:state.data.currency,minimumFractionDigits:decimals,maximumFractionDigits:decimals}).format(n);}
function number(n,d=2){return new Intl.NumberFormat('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);}
function date(d){return new Date(d+'T00:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});}
function shortDate(d){return new Date(d+'T00:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'});}
function log(message){state.log.push({time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),message});}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function download(name,body,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function head(kicker,title,subtitle,action=''){return `<div class="pagehead"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="sub">${subtitle}</p></div>${action}</div>`;}
function metric(label,value,meta,accent=false){return `<div class="metric ${accent?'accent':''}"><div class="label">${label}</div><div class="value">${value}</div><div class="meta">${meta}</div></div>`;}
function button(label,action,cls=''){return `<button class="button ${cls}" data-action="${action}">${label}</button>`;}
const frameworkNames={asc842:'US GAAP · ASC 842',ifrs16:'IFRS 16',indas116:'Ind AS 116'};
function effectiveType(){return state.framework==='asc842'?state.data.type:'finance';}
function effectiveData(){return state.framework==='asc842'?state.data:{...state.data,type:'finance'};}
function calc(){return calculate(effectiveData());}
function row(){return calc().rows[state.month-1];}
function stepTo(view){if(['schedule','journals','recon'].includes(view)&&!state.approved){toast('Review and approve the assumptions first.');view=state.extracted?'review':'intake';}if(view==='review'&&!state.extracted){toast('Extract the sample PDF first.');view='intake';}state.view=view;state.error='';render();window.scrollTo({top:0,behavior:'smooth'});}
function intake(){return head('INTERACTIVE FINANCE CASE STUDY','From lease to ledger.','Read a sample lease, review the assumptions and follow every amount through to the monthly close.',`<span class="pill neutral">Working prototype · v1.0</span>`)+`
<div class="grid2"><section class="card"><div class="cardhead"><h2>Start with the source document</h2><span class="pill">Sample ready</span></div>
<div class="documenttitle"><div class="fileicon">PDF</div><div><strong>Larkbrook · Noida office lease</strong><div class="muted small">2 pages · Fictional agreement · Text-based PDF</div></div></div>
<p class="sub">A three-year lease with fixed rent increases, three rent-free months and an upfront incentive.</p>
<div class="steps"><div><span class="stepnum">1</span><div><strong>Extract or capture eight contractual fields</strong><p>From the sample PDF, with page and source wording, or from your own CSV template.</p></div></div><div><span class="stepnum">2</span><div><strong>Approve accounting assumptions</strong><p>Confirm the rate, classification and direct costs.</p></div></div><div><span class="stepnum">3</span><div><strong>Calculate, book and reconcile</strong><p>Export schedules and journal proposals; resolve a sample GL difference.</p></div></div></div>
<div class="actions"><button class="button" data-action="extract" ${state.busy?'disabled':''}>${state.busy?'Reading PDF…':'Extract sample lease'} <span aria-hidden="true">→</span></button><a class="button secondary" href="sample-lease.pdf" download>Download sample PDF</a></div>
${state.busy?'<div class="progressline" role="progressbar" aria-label="Reading sample lease"></div>':''}
${state.error?`<div class="note error" role="alert">${esc(state.error)}</div>`:''}
<div class="note"><strong>Transparent demo mode.</strong> PDF text extraction and template matching are real. Clause interpretation is limited to the sample labels; no live AI model or OCR is connected.</div>
<div class="upload"><label for="pdfUpload">Or use a text PDF with the same field labels</label><input id="pdfUpload" type="file" accept="application/pdf,.pdf"><p class="small muted" style="margin:9px 0 0">Matches this template's exact labels only — it won't parse an arbitrary lease PDF. Up to 10 MB and 30 pages; unsupported or incomplete documents are flagged, not guessed.</p></div>
<div class="upload"><label for="csvUpload">Or bring your own numbers with a CSV template</label><input id="csvUpload" type="file" accept=".csv,text/csv"><p class="small muted" style="margin:9px 0 6px">Deterministic field capture from a defined two-column template — not document extraction, and it won't read an arbitrary spreadsheet.</p>${button('Download the CSV template','download-template','secondary')}</div>
<div class="quickstats"><div><strong>36</strong><span>monthly periods</span></div><div><strong>8</strong><span>traceable fields</span></div><div><strong>1</strong><span>review gate</span></div></div></section>
<section class="card"><div class="cardhead"><h2>Lease at a glance</h2><span class="small muted">DEMO-001</span></div><div class="doccanvas"><div class="document"><div class="docheader"><span>FICTIONAL AGREEMENT</span><span>01 / 02</span></div><div class="doctitle">Office lease<br>Commercial terms</div><div class="docline"><b>Lessee</b><br>Larkbrook Software India Pvt Ltd</div><div class="docline"><b>Commencement</b> <span class="fieldtag">01 January 2026</span></div><div class="docline"><b>Lease term</b> <span class="fieldtag">36 months</span></div><div class="docline"><b>Monthly rent</b> <span class="fieldtag">INR 100,000</span></div><div class="docline"><b>Annual increase</b> 5% compounded</div><div class="docline"><b>Rent-free period</b> First 3 months</div><div class="docline"><b>Cash incentive</b> INR 60,000</div><div class="docfooter">Illustrative excerpt · Download the full sample above</div></div></div><div class="note warn"><strong>A useful control:</strong> the signing date, rent start date and accounting commencement date need not be the same. This sample makes availability explicit.</div><p class="small muted">Scope: one lessee, one currency, monthly payments in arrears and a commencement date on the first day of a month.</p><button class="textbutton" data-view="case">See methodology and demo boundaries →</button></section></div>`;}
function field(key,type='number',hint=''){
 const v=state.data[key],ev=state.evidence[key];let control='';
 if(key==='currency')control=`<select name="currency" id="f-currency">${['INR','USD','EUR','GBP'].map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}</select>`;
 else if(key==='type')control=`<select name="type" id="f-type"><option value="operating" ${v==='operating'?'selected':''}>Operating lease</option><option value="finance" ${v==='finance'?'selected':''}>Finance lease — simplified comparison</option></select>`;
 else control=`<input name="${key}" id="f-${key}" type="${type}" value="${esc(v)}" ${type==='number'?'step="any" min="0"':''} required>`;
 return `<div class="field ${key==='entity'?'full':''}"><label for="f-${key}">${labels[key]}</label>${control}${hint?`<small>${hint}</small>`:''}${ev?`<div class="source"><details><summary>Source · page ${ev.page}</summary><blockquote>${esc(ev.quote)}</blockquote></details></div>`:''}</div>`;
}
function review(){return head('STEP 02 / HUMAN REVIEW','Approve the facts. Own the judgment.','Source terms and management assumptions are deliberately separate. Editing an approved lease invalidates its previous approval.',`<span class="pill ${state.approved?'':'amber'}">${state.approved?'Reviewed in demo':'Review required'}</span>`)+`
<form id="reviewForm"><div class="grid2"><section class="card"><div class="cardhead"><h2>Extracted lease terms</h2><span class="pill">8 fields · ${state.source==='csv'?'template values':'source linked'}</span></div><p class="small muted">${esc(state.filename)} · ${state.source==='csv'?'CSV template values; review every entry.':'Template extraction; review every value.'}</p><div class="fieldgrid">${field('entity','text')}${field('currency')}${field('start','date')}${field('months','number','Whole months; maximum 120.')}${field('rent')}${field('escalation','number','Fixed increase on each lease anniversary.')}${field('free','number','Applies at the start of the lease.')}${field('incentive','number','Cash received at commencement.')}</div></section>
<section class="card"><div class="cardhead"><h2>Management assumptions</h2><span class="pill amber">Not contract extraction</span></div><div class="fieldgrid">${field('type','number','ASC 842 only — IFRS 16 and Ind AS 116 do not classify leases this way. See the classification test below.')}${field('rate','number','Nominal annual rate, compounded monthly: annual rate ÷ 12. Build one up below if you don\'t have a rate implicit in the lease.')}${field('idc','number','Sample: 12,000 of qualifying costs already paid.')}${field('prepayment','number','Already paid; additional to the scheduled rents.')}</div><div class="note warn"><strong>Classification and the discount rate are reviewed inputs.</strong> The classification test and IBR build-up below illustrate the judgment; they do not replace it. The finance comparison assumes no ownership transfer or purchase option, and a useful life no shorter than the lease term.</div><div class="note">Changing currency changes the unit of account only. This demo does not translate amounts or calculate FX.</div></section></div>
${classificationPanel()}
${ibrPanel()}
${state.error?`<div class="note error" role="alert">${esc(state.error)}</div>`:''}
<div class="approval"><label class="checkrow"><input type="checkbox" id="reviewCheck" required><span>I have reviewed the source fields and the illustrative accounting assumptions. I understand the scope limitations.</span></label><div class="actions"><button class="button" type="submit">Approve & calculate →</button></div></div></form>`;}
function clsField(key,label,kind='number'){
 const v=state.classification[key];
 const control=kind==='bool'?`<label class="checkrow" style="margin-top:2px"><input type="checkbox" data-control="cls-${key}" ${v?'checked':''}><span>${v?'Yes':'No'}</span></label>`:`<input type="number" step="any" min="0" data-control="cls-${key}" value="${v}">`;
 return `<div class="field"><label>${label}</label>${control}</div>`;
}
function classificationPanel(){
 const initLiab=calculate(state.data).initialLiability;
 const t=classificationTest({...state.classification,months:state.data.months},initLiab);
 const rows=[
  ['Ownership transfers to the lessee by the end of the term',t.criteria[0],state.classification.ownershipTransfer?'Transfers':'Does not transfer'],
  ['Lessee is reasonably certain to exercise a purchase option',t.criteria[1],state.classification.purchaseOption?'Reasonably certain':'No, or not reasonably certain'],
  [`Lease term is a major part of the remaining economic life (policy threshold ${state.classification.termThreshold}%)`,t.criteria[2],`${state.data.months} of ${state.classification.economicLifeMonths} months · ${number(t.termPct*100,1)}%`],
  [`PV of lease payments is substantially all of the asset's fair value (policy threshold ${state.classification.pvThreshold}%)`,t.criteria[3],`${money(initLiab,0)} of ${money(state.classification.fairValue,0)} · ${number(t.pvPct*100,1)}%`],
  ['Asset is so specialized it has no alternative use to the lessor',t.criteria[4],state.classification.specializedAsset?'No alternative use':'General-purpose asset'],
 ];
 return `<section class="card"><div class="cardhead"><h2>US GAAP classification test — is this a finance lease?</h2><span class="pill ${t.finance?'amber':''}">${t.finance?'At least one criterion met → finance lease':'No criterion met → operating lease'}</span></div>
<p class="small muted">ASC 842-10-25-2 classifies a lease as finance if it meets any of five criteria at commencement; otherwise it is an operating lease. <strong>IFRS 16 and Ind AS 116 have no equivalent lessee classification</strong> — every lease is measured the same way, using the finance-style pattern shown for those frameworks on the schedules screen.</p>
<div class="fieldgrid">${clsField('ownershipTransfer','Ownership transfer at end of term','bool')}${clsField('purchaseOption','Reasonably certain purchase option','bool')}${clsField('economicLifeMonths','Remaining economic life (months)')}${clsField('fairValue',`Fair value of the asset (${state.data.currency})`)}${clsField('specializedAsset','Specialized asset, no alternative use','bool')}${clsField('termThreshold','Term policy threshold (%)')}${clsField('pvThreshold','PV policy threshold (%)')}</div>
<div class="tablewrap"><table><thead><tr><th>Criterion</th><th>Measured</th><th>Result</th></tr></thead><tbody>${rows.map(([label,crit,detail])=>`<tr><td>${label}</td><td class="small muted">${detail}</td><td><span class="pill ${crit.met?'amber':''}">${crit.met?'Met':'Not met'}</span></td></tr>`).join('')}</tbody></table></div>
<p class="small muted" style="margin:12px 0 0">Illustrative facts for this demo, not derived from the sample lease document. The 75%/90% figures are a common bright-line policy convention some preparers use as a practical expedient — ASC 842 itself does not mandate a specific percentage. Editing these facts updates the test live; it does not change the reviewed Lease classification field above, which stays a human judgment.</p></section>`;}
function ibrField(key,label){return `<div class="field"><label>${label}</label><input type="number" step="any" data-control="ibr-${key}" value="${state.ibr[key]}"></div>`;}
function ibrPanel(){
 const rate=ibrBuildUp(state.ibr.reference,state.ibr.spread,state.ibr.adjustment);
 return `<section class="card"><details><summary style="cursor:pointer;font-weight:650;font-size:16px">Optional: build up the discount rate (incremental borrowing rate)</summary>
<p class="small muted" style="margin:14px 0">All three frameworks share the same discount-rate principle: use the rate implicit in the lease if it's readily determinable, otherwise the lessee's incremental borrowing rate — what this entity would pay to borrow, over a similar term and with similar collateral, the funds to obtain an asset of similar value.</p>
<div class="fieldgrid">${ibrField('reference','Reference rate (%)')}${ibrField('spread','Lessee credit spread (%)')}${ibrField('adjustment','Term / collateral adjustment (%)')}</div>
<div class="tablewrap"><table><tbody><tr><td>Reference rate</td><td class="num">${number(state.ibr.reference,3)}%</td></tr><tr><td>+ Credit spread</td><td class="num">${number(state.ibr.spread,3)}%</td></tr><tr><td>+ Term / collateral adjustment</td><td class="num">${number(state.ibr.adjustment,3)}%</td></tr><tr><td><strong>Computed incremental borrowing rate</strong></td><td class="num"><strong>${number(rate,2)}%</strong></td></tr></tbody></table></div>
<div class="actions" style="margin-top:14px">${button('Use this rate','use-ibr-rate','secondary')}<span class="small muted">Sets the discount rate field above to ${number(rate,2)}%.</span></div>
</details></section>`;}
function chart(c){const values=[{v:c.initialLiability,r:c.initialROU},...c.rows.map(x=>({v:x.closeLiability,r:x.closeROU}))],max=Math.max(...values.flatMap(x=>[x.v,x.r]))||1;
 const w=760,h=175,left=65,top=15,plot=650;const path=key=>values.map((v,i)=>`${i?'L':'M'}${left+i/(values.length-1)*plot},${top+h-v[key]/max*h}`).join(' ');
 return `<svg class="chart" viewBox="0 0 760 225" role="img" aria-label="Liability and ROU asset decline to zero across the lease term">${[0,.5,1].map(f=>`<line x1="65" x2="715" y1="${top+h-h*f}" y2="${top+h-h*f}" stroke="#e0e8ef"/><text x="55" y="${top+h-h*f+4}" text-anchor="end">${number(max*f/1e6,1)}m</text>`).join('')}<path d="${path('v')}" fill="none" stroke="#007d71" stroke-width="2.7"/><path d="${path('r')}" fill="none" stroke="#287bc5" stroke-width="2.5"/><text x="65" y="218">Commencement</text><text x="715" y="218" text-anchor="end">Month ${state.data.months}</text></svg>`;}
function frameworkTabs(){return `<div class="tabs" role="tablist" aria-label="Accounting framework">${Object.entries(frameworkNames).map(([k,label])=>`<button role="tab" aria-selected="${state.framework===k}" class="${state.framework===k?'active':''}" data-framework="${k}">${label}</button>`).join('')}</div>
<p class="small muted" style="margin-bottom:20px">${state.framework==='asc842'?`Reviewed classification: <strong>${state.data.type==='operating'?'Operating':'Finance'} lease</strong>. See the classification test on the review screen for why.`:'IFRS 16 and Ind AS 116 lessees do not classify leases as operating or finance. Every lease — including this one — is measured with a single on-balance-sheet model from day one, shown below using the same interest-plus-amortization mechanics ASC 842 applies to a finance lease.'}</p>`;}
function schedule(){const c=calc(),r=row(),effType=effectiveType();const selected=state.tab;const columns=selected==='liability'?[['openLiability','Opening liability'],['interest','Accretion'],['payment','Payment'],['closeLiability','Closing liability'],['currentLiability','Current'],['noncurrentLiability','Noncurrent']]:[['openROU','Opening ROU'],['expense',effType==='operating'?'Lease expense':'Total expense'],['interest','Accretion / interest'],['amortization','ROU reduction'],['closeROU','Closing ROU']];
 return head('STEP 03 / DETERMINISTIC CALCULATIONS','Every month, accounted for.',`${esc(state.data.entity)} · ${state.data.currency} · ${state.data.months} months`,`<div class="actions">${button('Download schedules CSV','export-schedule','secondary')}${button('View monthly journals →','journals')}</div>`)+
frameworkTabs()+`
<div class="metrics">${metric('Initial lease liability',money(c.initialLiability),'PV of unpaid rents',true)}${metric('Initial ROU asset',money(c.initialROU),'Liability + prepayments − incentive + costs')}${metric(effType==='operating'?'Monthly lease expense':'Monthly ROU amortization',money(effType==='operating'?c.straightLine:c.initialROU/state.data.months),'Full-month convention')}${metric('Scheduled rent payments',money(c.totalCash),'Includes rent-free period and fixed increases')}</div>
<div class="grid2"><section class="card"><div class="cardhead"><h2>Liability and asset run-off</h2><div class="legend"><span><i></i>Liability</span><span><i class="blue"></i>ROU</span></div></div>${chart(c)}</section><section class="card"><div class="cardhead"><h2>Calculation bridge</h2><span class="pill">Reviewable formulas</span></div><div class="tablewrap"><table><tbody><tr><td>Present value of unpaid rents</td><td class="num">${money(c.initialLiability,2)}</td></tr><tr><td>+ Prepaid rent</td><td class="num">${money(+state.data.prepayment,2)}</td></tr><tr><td>− Incentive received</td><td class="num">${money(+state.data.incentive,2)}</td></tr><tr><td>+ Initial direct costs</td><td class="num">${money(+state.data.idc,2)}</td></tr><tr><td><strong>Initial ROU asset</strong></td><td class="num"><strong>${money(c.initialROU,2)}</strong></td></tr></tbody></table></div><p class="small muted" style="margin:12px 0 0">Monthly periodic rate: ${number(c.periodicRate*100,6)}%. Payments occur at month-end. Cash payments round to cents; calculations retain precision. Journals use rounded balance movements.</p></section></div>
${pvWorking(c)}
${expenseWorking(c)}
<section class="card"><div class="cardhead"><h2>Monthly roll-forward</h2><span class="pill">Final balances: ${money(c.rows.at(-1).closeLiability,2)} / ${money(c.rows.at(-1).closeROU,2)}</span></div><div class="tabs" role="tablist" aria-label="Schedule type"><button role="tab" aria-selected="${selected==='liability'}" class="${selected==='liability'?'active':''}" data-tab="liability">Lease liability</button><button role="tab" aria-selected="${selected==='rou'}" class="${selected==='rou'?'active':''}" data-tab="rou">ROU asset & expense</button><button role="tab" aria-selected="${selected==='maturity'}" class="${selected==='maturity'?'active':''}" data-tab="maturity">Annual cash maturities</button></div>
${selected==='maturity'?maturities(c):`<div class="tablewrap"><table><thead><tr><th>Period</th>${columns.map(x=>`<th class="num">${x[1]}</th>`).join('')}</tr></thead><tbody>${c.rows.map(x=>`<tr class="${x.month===state.month?'selectedrow':''}"><td>${shortDate(x.date)}${x.payment===0?' <span class="pill neutral">Free</span>':''}</td>${columns.map(([k])=>`<td class="num">${number(x[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
<div class="tablefoot"><span>${state.data.currency} · Current liability uses next 12 months’ principal reduction, floored at zero.</span><span>Rounding can produce 0.01 differences between displayed columns.</span></div></section>`;}
function maturities(c){const groups={};c.rows.forEach(r=>{const year=r.date.slice(0,4);groups[year]=(groups[year]||0)+r.payment;});return `<p class="small muted">Undiscounted scheduled rents by calendar year, measured at commencement. This is disclosure support, not a complete ASC 842 footnote.</p><div class="tablewrap"><table><thead><tr><th>Calendar year</th><th class="num">Cash payments (${state.data.currency})</th></tr></thead><tbody>${Object.entries(groups).map(([y,v])=>`<tr><td>${y}</td><td class="num">${number(v)}</td></tr>`).join('')}<tr><td>Total undiscounted rents</td><td class="num">${number(c.totalCash)}</td></tr><tr><td>Less: imputed interest</td><td class="num">(${number(c.totalCash-c.initialLiability)})</td></tr><tr><td><strong>Initial lease liability</strong></td><td class="num"><strong>${number(c.initialLiability)}</strong></td></tr></tbody></table></div>`;}
function pvWorking(c){const groups={};c.rows.forEach(r=>{const year=r.date.slice(0,4);groups[year]??={cash:0,pv:0};groups[year].cash+=r.payment;groups[year].pv+=r.presentValue;});
 const yearly=Object.entries(groups).map(([y,g])=>`<tr><td>${y}</td><td class="num">${number(g.cash)}</td><td class="num">${number(g.pv,2)}</td></tr>`).join('');
 return `<section class="card"><div class="cardhead"><h2>PV of unpaid rents — full working</h2><span class="pill">Ties to ${money(c.initialLiability,2)}</span></div>
<p class="small muted">Each unpaid rent is discounted from its month-end payment date back to commencement at the monthly periodic rate of ${number(c.periodicRate*100,4)}%. PV = Σ Rentₙ ÷ (1 + monthly rate)ⁿ, where n is the number of months from commencement to the payment.</p>
<div class="tablewrap"><table><thead><tr><th>Lease year</th><th class="num">Cash rent</th><th class="num">Present value</th></tr></thead><tbody>${yearly}<tr><td><strong>Total</strong></td><td class="num"><strong>${number(c.totalCash)}</strong></td><td class="num"><strong>${number(c.initialLiability,2)}</strong></td></tr></tbody></table></div>
<details class="pvdetail"><summary>Show all ${c.rows.length} monthly discount calculations</summary><div class="tablewrap"><table><thead><tr><th>Month</th><th>Period</th><th class="num">Rent</th><th class="num">Discount factor</th><th class="num">Present value</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${r.month}</td><td>${shortDate(r.date)}</td><td class="num">${number(r.payment)}</td><td class="num">${number(r.discountFactor,6)}</td><td class="num">${number(r.presentValue,2)}</td></tr>`).join('')}</tbody></table></div></details>
<p class="small muted" style="margin:12px 0 0">Excel equivalent: <code>=NPV(annual_rate/12, monthly_rent_range)</code> over the same monthly cash flows.</p></section>`;}
function expenseWorking(c){
 if(effectiveType()!=='operating')return `<section class="card"><div class="cardhead"><h2>Monthly ROU amortization — build-up</h2><span class="pill">Ties to ${money(c.initialROU/state.data.months,2)}</span></div><div class="tablewrap"><table><tbody><tr><td>Initial ROU asset</td><td class="num">${money(c.initialROU,2)}</td></tr><tr><td>÷ Lease term (months)</td><td class="num">${state.data.months}</td></tr><tr><td><strong>Monthly ROU amortization</strong></td><td class="num"><strong>${money(c.initialROU/state.data.months,2)}</strong></td></tr></tbody></table></div><p class="small muted" style="margin:12px 0 0">Interest is accreted separately on the liability each period at the periodic rate above. Amortization is a straight-line split of the initial ROU asset over the term, unrelated to the payment pattern, so total expense (interest + amortization) declines over the term rather than staying flat.${state.framework!=='asc842'?` This is the only pattern ${frameworkNames[state.framework]} uses — for every lease, not only ones ASC 842 would call finance.`:' This is the ASC 842 finance-lease pattern.'}</p></section>`;
 const totalCost=c.totalCash+(+state.data.prepayment)-(+state.data.incentive)+(+state.data.idc);
 return `<section class="card"><div class="cardhead"><h2>Monthly lease expense — straight-line build-up</h2><span class="pill">Ties to ${money(c.straightLine,2)}</span></div>
<div class="tablewrap"><table><tbody><tr><td>Total scheduled rent</td><td class="num">${money(c.totalCash,2)}</td></tr><tr><td>+ Prepaid rent</td><td class="num">${money(+state.data.prepayment,2)}</td></tr><tr><td>− Incentive received</td><td class="num">${money(+state.data.incentive,2)}</td></tr><tr><td>+ Initial direct costs</td><td class="num">${money(+state.data.idc,2)}</td></tr><tr><td>Total cost of the lease</td><td class="num">${money(totalCost,2)}</td></tr><tr><td>÷ Lease term (months)</td><td class="num">${state.data.months}</td></tr><tr><td><strong>Monthly lease expense</strong></td><td class="num"><strong>${money(c.straightLine,2)}</strong></td></tr></tbody></table></div>
<p class="small muted" style="margin:12px 0 0">ASC 842-20-25-6(a) requires the total cost of an operating lease — every scheduled rent payment, plus initial direct costs, less any incentive — to be recognized on a straight-line basis over the term. That single total, divided evenly by ${state.data.months} months, is why the expense stays ${money(c.straightLine,2)} every month: during the rent-free period, after each fixed escalation, and however uneven the underlying cash actually is. The liability's accretion and the ROU asset's amortization move independently underneath, but by construction they always add back to this same figure (see the liability and ROU asset & expense tabs below).</p></section>`;}
function periodSelect(c){return `<div class="field"><label for="period">Close period</label><select id="period" data-control="month">${c.rows.map(r=>`<option value="${r.month}" ${r.month===state.month?'selected':''}>${shortDate(r.date)} · Month ${r.month}</option>`).join('')}</select></div>`;}
function journalTable(rows){const d=rows.reduce((s,x)=>s+x.debit,0),c=rows.reduce((s,x)=>s+x.credit,0);return `<div class="tablewrap"><table><thead><tr><th>GL account</th><th class="num">Debit (${state.data.currency})</th><th class="num">Credit (${state.data.currency})</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.account)}</td><td class="num">${x.debit?number(x.debit):'—'}</td><td class="num">${x.credit?number(x.credit):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total</td><td class="num">${number(d)}</td><td class="num">${number(c)}</td></tr></tfoot></table></div><div class="tablefoot"><span>Illustrative chart of accounts · ${esc(state.data.leaseId)}</span><span class="balance">${Math.abs(d-c)<.005?'✓ Debits equal credits':'Review rounding difference'}</span></div>`;}
function journalPage(){const c=calc(),r=row(),rows=state.journalMode==='initial'?initialJournals(effectiveData(),c):[...journals(effectiveData(),r,state.route),...reclassJournalRows(effectiveData(),r)];const groups={};rows.forEach(x=>(groups[x.event]??=[]).push(x));return head('STEP 04 / JOURNAL PROPOSALS','A clear path into the books.','Review the posting route before exporting. Journal files are proposals; this demo never posts to an ERP.',`<div class="actions">${button('Export all journal proposals','export-journals','secondary')}${button('Reconcile GL →','recon')}</div>`)+`
<section class="card"><div class="toolbar">${periodSelect(c)}<div class="field"><label for="apRoute">AP treatment</label><select id="apRoute" data-control="route"><option value="liability" ${state.route==='liability'?'selected':''}>Invoice debits lease liability</option><option value="expense" ${state.route==='expense'?'selected':''}>AP already booked rent expense</option></select></div></div><div class="note ${state.route==='expense'?'warn':''}">${state.route==='expense'?'<strong>Prevent duplicate rent expense.</strong> The proposal reclassifies fixed rent from AP rent expense to lease liability. Do not post the invoice again.':'<strong>Invoice route.</strong> Monthly measurement and the fixed-rent invoice are separate entries. The invoice debits lease liability; it does not add rent expense.'} Bank settlement remains Dr AP / Cr bank and is outside this export. No tax or service components are included.</div>
<p class="small muted" style="margin:14px 0 0">Journals below reflect the <strong>${frameworkNames[state.framework]}</strong> pattern selected on the schedules screen. Change the framework there to compare postings.</p>
<div class="tabs" role="tablist" aria-label="Journal date"><button role="tab" aria-selected="${state.journalMode==='monthly'}" data-journal="monthly" class="${state.journalMode==='monthly'?'active':''}">${shortDate(r.date)} journals</button><button role="tab" aria-selected="${state.journalMode==='initial'}" data-journal="initial" class="${state.journalMode==='initial'?'active':''}">Commencement entry</button></div>
${state.journalMode==='initial'?'<p class="small muted">Prepayment, incentive and direct-cost clearing balances are assumed to have been recorded before this recognition entry. The sample incentive clearing has a credit balance; costs and prepayments have debit balances. Commencement splits the liability directly into its current and noncurrent portions.</p>':''}
${state.journalMode==='monthly'?'<p class="small muted">A current/noncurrent reclassification entry appears only when the twelve-month current portion changes, moving the difference between the 220101 (current) and 220102 (noncurrent) subledger accounts. Together they always equal the total lease liability.</p>':''}
${Object.entries(groups).map(([name,rows])=>`<div class="journalgroup">${name.replaceAll('-',' ')} · ${date(rows[0].date)}</div>${journalTable(rows)}`).join('')}
<p class="small muted" style="margin:22px 0 0">The export includes commencement and every monthly proposal. Journal amounts reconcile to rounded balance movements; expense can vary by a cent from the displayed schedule. A stable posting key helps identify repeated imports; duplicate prevention must be enforced by the receiving ERP.</p></section>`;}
function seedGL(){const r=row();state.gl={liability:round2(r.closeLiability+(state.scenario==='missing'?r.payment:0)),rou:round2(r.closeROU),expense:round2(r.expense+(state.scenario==='missing'?r.payment:0)),currentLiability:round2(r.currentLiability)};state.projected=false;}
function reconRows(){const r=row(),g=state.gl;return [{account:'Lease liability',key:'liability',expected:r.closeLiability,actual:g.liability},{account:'Net ROU asset',key:'rou',expected:r.closeROU,actual:g.rou},{account:'Current-month lease costs',key:'expense',expected:r.expense,actual:g.expense},{account:'Current portion of lease liability',key:'currentLiability',expected:r.currentLiability,actual:g.currentLiability}].map(x=>({...x,difference:round2(x.actual-round2(x.expected))}));}
function recon(){if(!state.gl)seedGL();const c=calc(),r=row(),items=reconRows(),exception=items.some(x=>Math.abs(x.difference)>.01),matched=items.every(x=>Math.abs(x.difference)<=.01),cash=round2(r.payment),pattern=cash>0&&Math.abs(items[0].difference-cash)<.01&&Math.abs(items[2].difference-cash)<.01&&Math.abs(items[1].difference)<.01;
 return head('STEP 05 / CLOSE CONTROL','Make the difference explainable.','Compare the subledger with illustrative GL balances, then model a correction without changing the original GL.',`<div class="actions">${button('Download reconciliation CSV','export-recon','secondary')}</div>`)+`
<div class="metrics">${metric('Lease liability',money(r.closeLiability),`Expected · ${shortDate(r.date)}`,true)}${metric('Net ROU asset',money(r.closeROU),'Expected closing balance')}${metric('GL exceptions',String(items.filter(x=>Math.abs(x.difference)>.01).length),'Accounts outside 0.01 tolerance')}${metric('Review status',matched?'Matched':state.projected?'Modelled':'Investigate',state.projected?'Actual GL remains unchanged':'Illustrative balances only')}</div>
<section class="card"><div class="toolbar">${periodSelect(c)}<div class="field"><label for="scenario">GL scenario</label><select id="scenario" data-control="scenario"><option value="missing" ${state.scenario==='missing'?'selected':''}>Missing AP rent reclassification</option><option value="clean" ${state.scenario==='clean'?'selected':''}>All expected entries posted</option><option value="manual" ${state.scenario==='manual'?'selected':''}>Manual balance comparison</option></select></div></div>
<form id="glForm"><div class="inlineform">${[['liability','GL lease liability'],['rou','GL net ROU asset'],['expense','GL current-month lease costs'],['currentLiability','GL current portion of liability']].map(([key,title])=>`<div class="field"><label for="gl-${key}">${title}</label><input id="gl-${key}" name="${key}" type="number" step="0.01" value="${state.gl[key]}" required></div>`).join('')}</div><div class="actions" style="margin:17px 0 23px"><button class="button secondary" type="submit">Compare balances</button><span class="small muted">Enter positive asset, liability and expense balances in ${state.data.currency}.</span></div></form>
<div class="tablewrap"><table><thead><tr><th>GL account</th><th class="num">Subledger</th><th class="num">Actual demo GL</th><th class="num">GL − subledger</th>${state.projected?'<th class="num">Projected difference</th>':''}<th>Status</th></tr></thead><tbody>${items.map(x=>`<tr><td>${x.account}</td><td class="num">${number(x.expected)}</td><td class="num">${number(x.actual)}</td><td class="num ${Math.abs(x.difference)>.01?'diff':'zero'}">${number(x.difference)}</td>${state.projected?'<td class="num zero">0.00</td>':''}<td><span class="pill ${Math.abs(x.difference)>.01?'amber':''}">${Math.abs(x.difference)>.01?'Review':'Matched'}</span></td></tr>`).join('')}</tbody></table></div>
${pattern?`<div class="reconanalysis"><h3>Pattern: rent expense was not reclassified</h3><p class="small">Liability and expense are both overstated by ${money(cash,2)}, equal to this month’s fixed rent. In the seeded scenario, AP booked Dr rent expense / Cr AP, while the Dr lease liability / Cr rent expense reclassification was omitted.</p><p class="small"><strong>Proposed correction:</strong> Dr lease liability ${money(cash,2)} / Cr AP rent expense ${money(cash,2)}.</p><p class="small muted">For real data, inspect the AP invoice and journal population before concluding. A matching amount alone is not evidence.</p>${button(state.projected?'Correction already modelled':'Model correction in demo','model-correction','dark')}</div>`:matched?'<div class="note success"><strong>Balances match.</strong> This numerical tie does not by itself prove population completeness or validate accounting judgments.</div>':`<div class="note warn"><strong>Unexplained variance.</strong> Review posting dates, account mapping, omitted entries and duplicates. This demo will not create a balancing plug.</div>`}
${state.scenario==='missing'&&cash===0?'<div class="note">This month is rent-free, so there is no rent reclassification to omit. Select the first paid month to demonstrate the exception.</div>':''}
${state.projected?'<div class="note success">The proposed correction would clear both differences. Original GL values are preserved. Nothing has been posted or marked as actually reconciled.</div>':''}
<p class="small muted" style="margin:18px 0 0">This is a balance-level demonstration. A production reconciliation must also tie GL extract control totals, inspect transactions and verify completeness of the lease population.</p></section><section class="card"><div class="cardhead"><h2>Session activity</h2><span class="pill neutral">Demo audit trail</span></div>${audit()}</section>`;
}
function audit(){return `<ul class="audit">${state.log.length?state.log.slice().reverse().map(x=>`<li><time>${esc(x.time)}</time><span>${esc(x.message)}</span></li>`).join(''):'<li>No actions yet. Start with the sample lease.</li>'}</ul><p class="small muted">Session history resets on refresh.</p>`;}
function casePage(){return head('PORTFOLIO / SORABH GUPTA','Automation with accounting judgment.','A hands-on case study in reducing repetitive preparation while preserving traceability, review and close controls.',`<div class="actions">${button('Print case study','print','secondary')}${button('Start the walkthrough →','intake')}</div>`)+`
<section class="card"><div class="cardhead"><h2>The problem and the proposed improvement</h2></div><p>Lease terms are scattered across contracts, spreadsheet schedules and AP postings. Manual rekeying creates inconsistent assumptions; disconnected journals create unexplained GL differences.</p><p>This prototype connects document evidence, reviewed inputs, deterministic calculations, journal proposals and a reconciliation exception in one visible workflow.</p><div class="flow"><div><span>01 / READ</span>PDF text → structured fields</div><div><span>02 / REVIEW</span>Evidence → approved assumptions</div><div><span>03 / CALCULATE</span>Rules → schedules and journals</div><div><span>04 / CONTROL</span>Subledger → GL exceptions</div></div></section>
<div class="scopegrid"><section class="card"><h2>Working in this demonstration</h2><ul><li>Local PDF text extraction and template-based field matching, with page references and source wording.</li><li>A downloadable CSV template for deterministic field capture from your own numbers — no document parsing involved.</li><li>Editable assumptions with input validation and a review gate.</li><li>Operating lease calculations and a simplified finance comparison.</li><li>A one-lease view across US GAAP (ASC 842), IFRS 16 and Ind AS 116.</li><li>An illustrative ASC 842 five-criteria classification test and an IBR build-up, both with editable facts.</li><li>Commencement and monthly journal proposals with AP routes.</li><li>GL balance comparison and a modelled corrective entry.</li><li>CSV exports, formulas and a session activity history.</li></ul></section><section class="card"><h2>Not connected or automated here</h2><ul><li>No live AI model or general-purpose legal-clause interpretation.</li><li>No OCR for scanned documents; only supported text-PDF labels.</li><li>No automatic classification or IBR estimation — the facts behind both are entered, not derived from the lease document or market data.</li><li>No ERP posting, transaction matching or durable approval system.</li><li>No amendments, impairment, FX, CPI rent or full multi-GAAP books (disclosures and transition differences are out of scope).</li><li>No production accounting use, audit assurance or measured time savings is claimed.</li></ul></section></div><section class="card"><div class="cardhead"><h2>Production design: Microsoft workflow</h2><span class="pill neutral">Proposed next stage</span></div><div class="tablewrap"><table><thead><tr><th>Layer</th><th>Proposed implementation</th><th>Control objective</th></tr></thead><tbody><tr><td>Intake</td><td>SharePoint + Power Automate</td><td>Complete package; document version and lease ID</td></tr><tr><td>Extraction</td><td>Document Intelligence + approved AI service</td><td>Structured output; clause evidence; no guessed values</td></tr><tr><td>Review</td><td>Power Apps + Dataverse</td><td>Maker/checker approval and retained judgments</td></tr><tr><td>Accounting</td><td>Validated lease engine / existing subledger</td><td>Repeatable calculations and tested modifications</td></tr><tr><td>Posting</td><td>Controlled ERP API or import</td><td>Approved journals and duplicate prevention</td></tr><tr><td>Reconciliation</td><td>GL/AP extracts + deterministic matching</td><td>Control totals, transaction evidence and sign-off</td></tr><tr><td>Assistant</td><td>Copilot Studio</td><td>Explain approved results and route exceptions</td></tr></tbody></table></div></section>
<div class="scopegrid"><section class="card"><h2>Calculation conventions</h2><ul><li>One lease component; 1–120 whole months, starting on day one.</li><li>Monthly arrears; nominal annual discount rate divided by 12.</li><li>Fixed annual increases compound at each lease anniversary.</li><li>Rent-free months are included in the accounting term.</li><li>Incentive is received at commencement; prepayments and direct costs are already paid.</li><li>Current liability uses next 12 months’ principal reduction, floored at zero.</li><li>Finance comparison amortizes ROU over the lease term; no transfer or purchase option.</li><li>Currency is a label, not an FX calculation. Periods use calendar month-ends.</li></ul></section><section class="card"><h2>What to measure in a real pilot</h2><ul><li>Preparation time per lease before and after automation.</li><li>Accuracy of critical fields against independently reviewed abstracts.</li><li>Number and value of unsupported or overridden fields.</li><li>Journal rejection and duplicate-import rates.</li><li>Reconciliation exceptions and days to resolution.</li><li>Reviewer time, rework and completeness of evidence.</li></ul><div class="note">No efficiency percentage is claimed. Establish a baseline and measure a controlled pilot.</div></section></div>
<section class="card"><h2>Accounting and technology references</h2><p class="small muted" style="margin:8px 0 15px">The prototype demonstrates selected mechanics, not comprehensive ASC 842 compliance. Final policies and complex cases require technical accounting review.</p><div class="sources"><a href="https://github.com/Sorabh-Gupta-Finance/leaseflow-asc842" target="_blank" rel="noopener">View source on GitHub · Sorabh-Gupta-Finance/leaseflow-asc842</a><a href="https://dart.deloitte.com/USDART/home/codification/broad-transactions/asc842-10/roadmap-leasing/chapter-8-lessee-accounting/8-4-recognition-measurement" target="_blank" rel="noopener">Deloitte Roadmap · ASC 842 recognition and measurement</a><a href="https://dart.deloitte.com/USDART/home/codification/broad-transactions/asc842-10/roadmap-leasing/chapter-14-presentation/14-2-lessee" target="_blank" rel="noopener">Deloitte Roadmap · Current/noncurrent presentation</a><a href="https://learn.microsoft.com/en-us/azure/ai-services/document-intelligence/prebuilt/layout" target="_blank" rel="noopener">Microsoft · Document Intelligence layout extraction</a><a href="https://learn.microsoft.com/en-us/microsoft-copilot-studio/advanced-connectors" target="_blank" rel="noopener">Microsoft · Copilot Studio connectors</a></div></section>`;}
function render(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});const views={intake,review,schedule,journals:journalPage,recon,case:casePage};$('#main').innerHTML=views[state.view]();}
function applyExtracted(found,evidence,name,source,logMsg){
 state.data={...sample,...found};const errors=validate(state.data);if(errors.length)throw Error(errors.join(' '));
 state.extracted=true;state.approved=false;state.gl=null;state.evidence=evidence;state.filename=name;state.source=source;state.month=Math.min(4,state.data.months);state.view='review';state.error='';log(logMsg);
}
async function readPDF(bytes,name){
 const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.min.mjs';
 const pdf=await pdfjs.getDocument({data:new Uint8Array(bytes),isEvalSupported:false,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href}).promise;
 if(pdf.numPages>30){await pdf.destroy();throw Error('The demo supports up to 30 pages.');}
 const pages=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),t=await page.getTextContent();pages.push(t.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''));}await pdf.destroy();
 if(pages.join('').trim().length<80)throw Error('No usable text found. Scanned PDFs require OCR, which is not connected in this demo.');
 const data=extract(pages),text=pages.join('\n');
 if(data.missing.length)throw Error('Template extraction incomplete or conflicting: '+data.missing.map(x=>labels[x]).join(', ')+'. Use the sample field labels. No accounting was generated.');
 if(!/Payment timing:\s*Monthly in arrears/i.test(text)||!/Demo scope:\s*Fixed rent; monthly arrears; no options; no modifications\./i.test(text))throw Error('This document does not confirm the supported sample scope and payment convention. Use the fictional sample; arbitrary contracts need a live extraction service and technical review.');
 applyExtracted(data.found,data.evidence,name,'pdf','Extracted eight labelled contract fields from '+name+'; source pages retained.');
}
async function processPDF(file){state.busy=true;state.error='';render();try{if(file){if(file.size>10*1024*1024)throw Error('Use a PDF smaller than 10 MB.');await readPDF(await file.arrayBuffer(),file.name);}else{const response=await fetch('sample-lease.pdf');if(!response.ok)throw Error('The sample PDF could not be loaded. Please try again.');await readPDF(await response.arrayBuffer(),'sample-lease.pdf');}toast('Eight fields extracted. Review the assumptions next.');}catch(e){state.error=e.message||'Unable to read this PDF.';state.view='intake';}finally{state.busy=false;render();}}
function readCsv(text,name){
 const data=extractCsv(text);
 if(data.missing.length)throw Error('Template incomplete or invalid: '+data.missing.map(x=>labels[x]).join(', ')+'. Use the downloaded template, keep its field names, and fill in every row. No accounting was generated.');
 applyExtracted(data.found,{},name,'csv','Captured eight fields from a CSV template: '+name+'.');
}
async function processCsv(file){state.busy=true;state.error='';render();try{if(!file)throw Error('Choose a CSV file to upload.');if(!/\.csv$/i.test(file.name))throw Error('Use a .csv file exported from Excel, Google Sheets or Numbers.');if(file.size>200*1024)throw Error('Use a CSV file smaller than 200 KB.');readCsv(await file.text(),file.name);toast('Eight fields captured from your template. Review the assumptions next.');}catch(e){state.error=e.message||'Unable to read this CSV.';state.view='intake';}finally{state.busy=false;render();}}
function downloadTemplate(){download('LeaseFlow_template.csv',csv([{field:'entity',value:sample.entity},{field:'currency',value:sample.currency},{field:'start',value:sample.start},{field:'months',value:sample.months},{field:'rent',value:sample.rent},{field:'escalation',value:sample.escalation},{field:'free',value:sample.free},{field:'incentive',value:sample.incentive}]));toast('Template downloaded. Edit the values in Excel, save as CSV, then upload it below.');}
function approve(data,confirmed){if(!confirmed)throw Error('Confirm that you reviewed the sample inputs.');const errors=validate(data);if(errors.length)throw Error(errors.join(' '));calculate(data);state.data=data;state.approved=true;state.month=Math.min(state.month,+data.months);state.gl=null;state.projected=false;state.view='schedule';log('Demo reviewer approved assumptions; deterministic schedules generated.');render();}
function exportJournal(){const c=calc(),ed=effectiveData();const rows=[...initialJournals(ed,c),...c.rows.flatMap(r=>[...journals(ed,r,state.route),...reclassJournalRows(ed,r)])].map(x=>({postingKey:`${state.data.leaseId}-DEMO-v1-${x.date}-${x.event}`,status:'PROPOSAL-NOT-POSTED',framework:state.framework,...x}));download('LeaseFlow_journal_proposals.csv',csv(rows));log('Exported journal proposals; no ERP posting performed.');toast('Journal proposals downloaded.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.view){stepTo(b.dataset.view);return;}if(b.dataset.tab){state.tab=b.dataset.tab;render();return;}if(b.dataset.journal){state.journalMode=b.dataset.journal;render();return;}if(b.dataset.framework){state.framework=b.dataset.framework;render();return;}
 const action=b.dataset.action;if(!action)return;
 if(['intake','review','schedule','journals','recon'].includes(action)){stepTo(action);return;}
 if(action==='extract')processPDF();
 if(action==='download-template')downloadTemplate();
 if(action==='reset'){state={view:'intake',data:{...sample},extracted:false,approved:false,evidence:{},filename:'sample-lease.pdf',source:'pdf',month:4,tab:'liability',route:'liability',journalMode:'monthly',framework:'asc842',classification:{...classificationDefaults},ibr:{...ibrDefaults},gl:null,scenario:'missing',projected:false,error:'',busy:false,log:[]};render();toast('Demo reset.');}
 if(action==='use-ibr-rate'){const el=$('#f-rate'),rate=ibrBuildUp(state.ibr.reference,state.ibr.spread,state.ibr.adjustment);if(el){el.value=round2(rate);toast(`Discount rate field set to ${number(rate,2)}%. Review and approve to apply it.`);}}
 if(action==='export-schedule'){download('LeaseFlow_schedules.csv',csv(calc().rows.map(x=>({leaseId:state.data.leaseId,entity:state.data.entity,currency:state.data.currency,framework:state.framework,pattern:effectiveType(),...x}))));log('Exported liability and ROU schedules.');toast('Schedules downloaded.');}
 if(action==='export-journals')exportJournal();
 if(action==='model-correction'){state.projected=true;log('Modelled the omitted AP rent reclassification; original GL preserved.');render();toast('Correction modelled only. No posting performed.');}
 if(action==='export-recon'){download('LeaseFlow_reconciliation.csv',csv(reconRows().map(x=>({leaseId:state.data.leaseId,date:row().date,currency:state.data.currency,account:x.account,subledger:round2(x.expected),actualDemoGL:x.actual,difference:x.difference,projectedDifference:state.projected?0:'Not modelled',status:state.projected?'Correction modelled, not posted':Math.abs(x.difference)>.01?'Investigate':'Balance matched'}))));log('Exported illustrative GL reconciliation.');toast('Reconciliation downloaded.');}
 if(action==='print')window.print();
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='pdfUpload'&&el.files[0]){processPDF(el.files[0]);return;}
 if(el.id==='csvUpload'&&el.files[0]){processCsv(el.files[0]);return;}
 if(el.dataset.control?.startsWith('cls-')){state.classification[el.dataset.control.slice(4)]=el.type==='checkbox'?el.checked:Number(el.value);render();return;}
 if(el.dataset.control?.startsWith('ibr-')){state.ibr[el.dataset.control.slice(4)]=Number(el.value);render();return;}
 if(el.closest('#reviewForm')&&el.id!=='reviewCheck'&&state.approved){state.approved=false;toast('Input changed. Review and approve again.');}
 if(el.dataset.control==='month'){state.month=+el.value;state.gl=null;state.projected=false;render();}
 if(el.dataset.control==='route'){state.route=el.value;render();}
 if(el.dataset.control==='scenario'){state.scenario=el.value;if(state.scenario!=='manual')seedGL();state.projected=false;render();}
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='reviewForm'){
 const f=new FormData(e.target),data={...state.data};for(const k of Object.keys(labels))data[k]=['entity','currency','start','type'].includes(k)?String(f.get(k)):Number(f.get(k));
 try{approve(data,$('#reviewCheck').checked);toast('Inputs approved. Schedules are ready.');window.scrollTo({top:0,behavior:'smooth'});}catch(err){state.data=data;state.error=err.message;state.approved=false;render();}}
 if(e.target.id==='glForm'){const f=new FormData(e.target),g={liability:Number(f.get('liability')),rou:Number(f.get('rou')),expense:Number(f.get('expense')),currentLiability:Number(f.get('currentLiability'))};if(Object.values(g).some(x=>!Number.isFinite(x)||Math.abs(x)>1e12)){toast('Enter valid GL amounts below one trillion.');return;}state.gl=g;state.scenario='manual';state.projected=false;log('Compared entered GL balances with the approved subledger.');render();}
});
render();
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_lease_demo_state',title:'Read lease demo state',description:'Read the current demo stage, approved assumptions and calculated balances. Does not modify the workflow.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {view:state.view,extracted:state.extracted,approved:state.approved,assumptions:state.data,results:state.approved?{initialLiability:calc().initialLiability,initialROU:calc().initialROU,period:row()}:null};}});
 register({name:'navigate_lease_demo',title:'Navigate lease demo',description:'Open a workflow step. Accounting results require prior review approval; this does not approve inputs or post journals.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['intake','review','schedule','journals','recon','case']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='view')||!['intake','review','schedule','journals','recon','case'].includes(input.view))throw Error('Invalid workflow view.');stepTo(input.view);return {view:state.view,approved:state.approved};}});
}
